cat > src/merge.js <<'EOF'
function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const output = []
  let conflict = false
  let pos = 0
  const sides = [mine, theirs]
  const stable = end => {
    if (end > pos) {
      const s = base.slice(pos, end)
      output.push({ kind: 'stable', lines: s })
    }
    pos = end
  }
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    const rb = base.slice(rs, re)
    const rep = who => {
      const g = group.filter(c => c.who === who)
      if (!g.length) return rb
      const first = g[0], last = g[g.length - 1]
      const s = first.ss - (first.bs - rs)
      const e = Math.max(...g.map(c => c.se), last.se) + (re - Math.max(...g.map(c => c.be)))
      return sides[who].slice(s, e)
    }
    const mi = rep(0), th = rep(1)
    if (eq(mi, th)) output.push({ kind: 'both', lines: mi })
    else if (eq(mi, rb)) output.push({ kind: 'theirs', lines: th })
    else if (eq(th, rb)) output.push({ kind: 'mine', lines: mi })
    else output.push({ kind: 'conflict', mine: mi, base: rb, theirs: th })
    pos = re
  }
  stable(base.length)
  const out = []
  for (const r of output) {
    if (r.kind === 'conflict') conflict = true
    if (mode === 'regions') {
      out.push(r.kind === 'conflict'
        ? `conflict mine=${r.mine.length} base=${r.base.length} theirs=${r.theirs.length}`
        : `${r.kind} ${r.lines.length}`)
    } else if (r.kind === 'conflict') {
      out.push('<<<<<<< mine', ...r.mine)
      if (mode === 'merge') out.push('||||||| base', ...r.base)
      out.push('=======', ...r.theirs, '>>>>>>> theirs')
    } else out.push(...r.lines)
  }
  return { output: out, conflict }
}
