{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  let seenBallot = false
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (candidates !== null || seenBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (candidates === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      seenBallot = true
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!COUNT.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  }
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
}

const { candidates, ballots } = parse(readFileSync(0, 'utf8'))
const continuing = new Set(candidates)
const history = new Map(candidates.map((c) => [c, []]))
const out = []
let round = 0
let winner = null

for (;;) {
  round++
  const votes = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      votes.set(c, votes.get(c) + b.count)
      active += b.count
    }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  for (const [c, v] of votes) history.get(c).push(v)
  const list = [...votes.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  out.push(`round ${round}: ${list.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) break
  const top = list.find(([, v]) => v * 2n > active)
  if (top) {
    winner = top[0]
    break
  }
  const min = list[list.length - 1][1]
  let tied = list.filter(([, v]) => v === min).map(([c]) => c)
  for (let r = 0; r < round && tied.length > 1; r++) {
    const m = tied.reduce((a, c) => (history.get(c)[r] < a ? history.get(c)[r] : a), history.get(tied[0])[r])
    tied = tied.filter((c) => history.get(c)[r] === m)
  }
  tied.sort()
  const elim = tied[tied.length - 1]
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}

const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${round}\n${end}\n`)
EOF
