  const isHex = (ch) => ch !== undefined && /^[0-9a-fA-F]$/.test(ch)
  const isLetter = (ch) => ch !== undefined && /^\p{L}$/u.test(ch)
  const isIdStart = (ch) => ch === '_' || isLetter(ch)
  const isIdCont = (ch) => isIdStart(ch) || isDigit(ch)
