        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) j = run(j + 1, isDigit)
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) j = run(j + 2, isDigit)
