const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  r.scheme = m[1] ?? null
  r.authority = m[2] ?? null
  r.path = m[3]
  r.query = m[4] ?? null
  r.fragment = m[5] ?? null
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const hp = a.slice(at + 1)
  const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1 || 0)
  let host = hp
  let port = null
  if (colon >= 0) {
    host = hp.slice(0, colon)
    port = hp.slice(colon + 1)
  }
  return { userinfo, host, port }
}

export function removeDotSegments(path) {
  let input = path
  const out = []
  while (input.length > 0) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out.pop()
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out.push(seg)
      input = input.slice(seg.length)
    }
  }
  return out.join('')
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

export class UriError extends Error {}

export function normalize(r) {
  let userinfo = null, host = null, port = null
  if (r.authority !== null) ({ userinfo, host, port } = splitAuthority(r.authority))
  const checks = [['path', r.path], ['userinfo', userinfo], ['host', host], ['query', r.query], ['fragment', r.fragment]]
  for (const [name, v] of checks) {
    if (v !== null && truncated(v)) throw new UriError(`the ${name} has a truncated percent-encoding`)
  }
  const scheme = r.scheme === null ? null : lower(r.scheme)
  let out = ''
  if (scheme !== null) out += scheme + ':'
  if (r.authority !== null) {
    let a = ''
    if (userinfo !== null) a += pct(userinfo) + '@'
    a += lower(pct(host))
    if (port !== null && port !== '' && port !== DEFAULT_PORTS[scheme]) a += ':' + pct(port)
    out += '//' + a
  }
  let path = removeDotSegments(pct(r.path))
  if (r.authority !== null && path === '') path = '/'
  out += path
  if (r.query !== null) out += '?' + pct(r.query)
  if (r.fragment !== null) out += '#' + pct(r.fragment)
  return out
}

export function resolve(base, ref) {
  const t = { scheme: null, authority: null, path: '', query: null, fragment: ref.fragment }
  if (ref.scheme !== null) {
    Object.assign(t, ref)
  } else if (ref.authority !== null) {
    Object.assign(t, ref, { scheme: base.scheme })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== null ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = ref.path
      else if (base.authority !== null && base.path === '') t.path = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        t.path = (i >= 0 ? base.path.slice(0, i + 1) : '') + ref.path
      }
      t.query = ref.query
    }
  }
  return t
}
