            : 'expected route <prefix> <policy>...')
        }
        if (lastTick !== null) throw new Fail('declarations must come before the first event')
        if (d === 'route') {
          if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
          if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
          for (const p of w.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
          routes.set(w[1], w.slice(2))
        } else {
          if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
          let pol
          if (d === 'bucket') {
            pol = { kind: 'bucket', name: w[1], capacity: count('capacity', w[2], 1), refill: count('refill', w[3], 0), per: count('per', w[4], 1) }
          } else {
            pol = { kind: 'window', name: w[1], limit: count('limit', w[2], 0), span: count('span', w[3], 1) }
          }
          if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
          policies.set(w[1], pol)
        }
      } else if (d === 'event') {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count('tick', w[1], 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, tickText: String(tick), key: w[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { policies, routes, events }
}

function run({ policies, routes, events }) {
  const states = new Map()
  const stateOf = (pol, key) => {
    const id = pol.name + '\0' + key
    return states.get(id) ?? (states.set(id, null), null)
  }
  const get = (pol, key, tick) => {
    const id = pol.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = pol.kind === 'bucket'
        ? { scaled: pol.capacity * pol.per, last: tick }
        : { ticks: [] }
      states.set(id, s)
    }
    return s
  }
