const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function check(name, s, n) {
  if (s !== null && /%(?![0-9A-Fa-f]{2})/.test(s)) throw new Fail(`error: line ${n}: the ${name} has a truncated percent-encoding`)
}

function normalize(t, n) {
  const a = splitAuth(t.authority)
  check('path', t.path, n)
  if (a) { check('userinfo', a.userinfo, n); check('host', a.host, n) }
  check('query', t.query, n)
