function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sorted = (m) => [...m.keys()].sort(cmp)

function json(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sorted(n.m)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + json(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + json(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sorted(n.m)) {
      const p = path === null ? k : path + '.' + k
      out.push(p + ' ' + n.m.get(k).t)
      keys(n.m.get(k), p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((v, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + v.t)
      keys(v, p, out)
    })
  }
}

export function render(root, mode) {
  if (mode === 'json') return json(root, 0) + '\n'
  const out = []
  keys(root, null, out)
  return out.map((l) => l + '\n').join('')
}
