    ex.items.push(nt)
    return { node: nt, path }
  }
  if (!ex) {
    const nt = table()
    nt.header = true
    parent.m.set(last, nt)
    return { node: nt, path }
  }
  if (ex.t !== 'table') fail(`${dotted(path)} is not a table`)
  if (ex.header) fail(`table ${dotted(path)} is defined twice`)
  ex.header = true
  return { node: ex, path }
}
