    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + json(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + json(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sorted(n.m)) {
      const p = path === null ? k : path + '.' + k
      out.push(p + ' ' + n.m.get(k).t)
      keys(n.m.get(k), p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((v, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + v.t)
      keys(v, p, out)
