class ConfigError extends Error {
  constructor(msg) {
    super(msg)
    this.isConfigError = true
  }
}

const table = () => ({ t: 'table', m: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isComment = (c) => c === '#' || c === ';'
const RUN = '[0-9]+(?:_[0-9]+)*'
const INT = new RegExp(`^[+-]?${RUN}$`)
const FLOAT = new RegExp(`^[+-]?${RUN}(?:\\.${RUN}(?:[eE][+-]?${RUN})?|[eE][+-]?${RUN})$`)

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = table()
  let current = root
  let currentPath = []
  for (let i = 0; i < lines.length; i++) {
    try {
      const st = { s: lines[i], p: 0 }
      const r = parseLine(st, root, current, currentPath)
      if (r) {
        current = r.node
        currentPath = r.path
      }
    } catch (e) {
      if (e.isConfigError) e.message = `line ${i + 1}: ${e.message}`
      throw e
    }
  }
  return root
}

function fail(m) {
  throw new ConfigError(m)
}

function skipWs(st) {
  while (isWs(st.s[st.p])) st.p++
}

function parseString(st) {
  const q = st.s[st.p++]
  let out = ''
  for (;;) {
    const c = st.s[st.p]
    if (c === undefined) fail('unterminated string')
    st.p++
    if (c === q) return out
    if (q === "'" || c !== '\\') {
      out += c
      continue
    }
    const e = st.s[st.p]
    if (e === undefined) fail('unterminated string')
    st.p++
    if (e === '"') out += '"'
    else if (e === '\\') out += '\\'
    else if (e === 'n') out += '\n'
    else if (e === 't') out += '\t'
    else if (e === 'r') out += '\r'
    else if (e === '0') out += '\0'
    else if (e === 'u') {
      const h = st.s.slice(st.p, st.p + 4)
      if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(h, 16))
      st.p += 4
    } else {
      const cp = String.fromCodePoint(st.s.codePointAt(st.p - 1))
      st.p += cp.length - 1
      fail(`invalid escape \\${cp}`)
    }
  }
}

function parseName(st) {
  const c = st.s[st.p]
  if (c === '"' || c === "'") return parseString(st)
  if (!isBare(c)) fail('expected a name')
  const a = st.p
  while (isBare(st.s[st.p])) st.p++
  return st.s.slice(a, st.p)
}

function parseDotted(st) {
  const names = [parseName(st)]
  for (;;) {
    const save = st.p
    skipWs(st)
    if (st.s[st.p] !== '.') {
      st.p = save
      return names
    }
    st.p++
    skipWs(st)
    names.push(parseName(st))
  }
}

function atEnd(st) {
  return st.s[st.p] === undefined || isComment(st.s[st.p])
}

function parseValue(st, base) {
  const c = st.s[st.p]
  if (c === undefined || isComment(c) || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"' || c === "'") return { t: 'string', v: parseString(st) }
  if (c === '[') return parseArray(st, base)
  if (c === '{') return parseInline(st, base)
  const a = st.p
  while (st.s[st.p] !== undefined && !isWs(st.s[st.p]) && !',]}'.includes(st.s[st.p])) st.p++
  const w = st.s.slice(a, st.p)
  if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
  if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
  if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
  fail(`invalid value ${w}`)
}

function parseArray(st, base) {
  st.p++
  const arr = { t: 'array', items: [], aot: false }
  let first = true
  for (;;) {
    skipWs(st)
    if (atEnd(st)) fail('unterminated array')
    if (st.s[st.p] === ']') {
      st.p++
      return arr
    }
    if (first || true) arr.items.push(parseValue(st, base + `[${arr.items.length}]`))
    first = false
    skipWs(st)
    const c = st.s[st.p]
    if (c === ',') st.p++
    else if (c === ']') {
      st.p++
      return arr
    } else fail('unterminated array')
  }
}

function parseInline(st, base) {
  st.p++
  const tbl = table()
  skipWs(st)
  if (st.s[st.p] === '}') {
    st.p++
    return tbl
  }
  for (;;) {
    skipWs(st)
    if (atEnd(st)) fail('unterminated inline table')
    const names = parseDotted(st)
    skipWs(st)
    if (st.s[st.p] !== '=') fail('expected = in an inline table')
    st.p++
    skipWs(st)
    const v = parseValue(st, base)
    assign(tbl, base, names, v)
    skipWs(st)
    const c = st.s[st.p]
    if (c === ',') st.p++
    else if (c === '}') {
      st.p++
      return tbl
    } else fail('unterminated inline table')
  }
}

const dotted = (p) => p.join('.')

// Walk (creating) tables through names; returns the table reached.
function walk(tbl, basePath, names) {
  let node = tbl
  const path = [...basePath]
  for (const n of names) {
    path.push(n)
    let next = node.m.get(n)
    if (!next) {
      next = table()
      node.m.set(n, next)
    } else if (next.t === 'array' && next.aot) {
      next = next.items[next.items.length - 1]
    } else if (next.t !== 'table') fail(`${dotted(path)} is not a table`)
    node = next
  }
  return { node, path }
}

function assign(tbl, basePath, names, value) {
  const base = typeof basePath === 'string' ? basePath : basePath
  const bp = Array.isArray(base) ? base : []
  const { node, path } = walk(tbl, bp, names.slice(0, -1))
  const last = names[names.length - 1]
  if (node.m.has(last)) fail(`key ${dotted([...path, last])} is defined twice`)
  node.m.set(last, value)
}

function parseLine(st, root, current, currentPath) {
  skipWs(st)
  if (atEnd(st)) return null
  if (st.s[st.p] === '[') return parseHeader(st, root)
  const names = parseDotted(st)
  skipWs(st)
  if (st.s[st.p] !== '=') fail('expected key = value')
  st.p++
  skipWs(st)
  const full = [...currentPath, ...names].join('.')
  const v = parseValue(st, full)
  skipWs(st)
  if (!atEnd(st)) fail('trailing text after a value')
  assign(current, currentPath, names, v)
  return null
}

function parseHeader(st, root) {
  st.p++
  let isArr = false
  if (st.s[st.p] === '[') {
    isArr = true
    st.p++
  }
  skipWs(st)
  const names = parseDotted(st)
  skipWs(st)
  if (st.s[st.p] !== ']') fail('unterminated table header')
  st.p++
  if (isArr) {
    if (st.s[st.p] !== ']') fail('unterminated table header')
    st.p++
  }
  skipWs(st)
  if (!atEnd(st)) fail('trailing text after a table header')
  const { node: parent, path } = walk(root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  path.push(last)
  const ex = parent.m.get(last)
  if (isArr) {
    if (!ex) {
      const nt = table()
      parent.m.set(last, { t: 'array', items: [nt], aot: true })
      return { node: nt, path }
    }
    if (ex.t !== 'array' || !ex.aot) fail(`${dotted(path)} is not an array of tables`)
    const nt = table()
    ex.items.push(nt)
    return { node: nt, path }
  }
  if (!ex) {
    const nt = table()
    nt.header = true
    parent.m.set(last, nt)
    return { node: nt, path }
  }
  if (ex.t !== 'table') fail(`${dotted(path)} is not a table`)
  if (ex.header) fail(`table ${dotted(path)} is defined twice`)
  ex.header = true
  return { node: ex, path }
}
