import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
let declared = new Set()
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const word = t[0]
  if (word === 'candidates') {
    if (names !== null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const list = []
    for (const nm of t.slice(1)) {
      if (!NAME.test(nm)) fail(`error: line ${n}: invalid candidate name ${nm}`)
      if (declared.has(nm)) fail(`error: line ${n}: candidate ${nm} is declared twice`)
      declared.add(nm)
      list.push(nm)
    }
    names = list
  } else if (word === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!declared.has(nm)) fail(`error: line ${n}: unknown candidate ${nm}`)
      if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${word}`)
  }
})
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = []
const out = []
let winner = null
for (;;) {
  const counts = new Map([...continuing].map((c) => [c, 0]))
  let active = 0
  let total = 0
  for (const b of ballots) {
    total += b.count
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const sorted = [...counts.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  let text = `round ${history.length}: ${sorted.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`
  out.push(text)
  if (active === 0) break
  const w = sorted.find(([, v]) => v * 2 > active)
  if (w) {
    winner = w[0]
    break
  }
  const min = Math.min(...counts.values())
  let tied = [...continuing].filter((c) => counts.get(c) === min)
  for (let r = 0; tied.length > 1 && r < history.length; r++) {
    const m = Math.min(...tied.map((c) => history[r].get(c)))
    tied = tied.filter((c) => history[r].get(c) === m)
  }
  const elim = tied.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
EOF
