    return die('error: usage: cli.js replay|summary')
  }
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let last = null
  try {
    lines.forEach((raw, i) => {
      const n = i + 1
      const fail = (r) => { throw new Fail(`error: line ${n}: ${r}`) }
      const line = raw.trim()
      if (line === '' || line.startsWith('#')) return
      const t = line.split(/\s+/)
      const num = (v, field, least) => {
        if (!INT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
        return BigInt(v)
      }
      const d = t[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (started) fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (t.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        const capacity = num(t[2], 'capacity', 1)
        const refill = num(t[3], 'refill', 0)
        const per = num(t[4], 'per', 1)
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
      } else if (d === 'window') {
        if (t.length !== 4) fail('expected window <name> <limit> <span>')
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        const limit = num(t[2], 'limit', 0)
        const span = num(t[3], 'span', 1)
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'window', name: t[1], limit, span })
      } else if (d === 'route') {
        if (t.length < 3) fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
        for (const p of t.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
        routes.set(t[1], t.slice(2).map((p) => policies.get(p)))
      } else if (d === 'event') {
        if (t.length !== 3) fail('expected event <tick> <key>')
        const tick = num(t[1], 'tick', 0)
        if (!NAME.test(t[2])) fail(`invalid key ${t[2]}`)
        if (last !== null && tick < last) fail(`tick ${tick} is before tick ${last}`)
        last = tick
        started = true
        events.push([tick, t[2]])
      } else fail(`unknown directive ${d}`)
    })
  } catch (e) {
    if (e instanceof Fail) return die(e.message)
    throw e
  }

  const states = new Map() // policy name -> Map key -> state
  const stateOf = (p, key) => {
    let m = states.get(p.name)
    if (!m) states.set(p.name, (m = new Map()))
    let s = m.get(key)
    if (!s) {
      s = p.kind === 'bucket' ? { tokens: p.capacity * p.per, at: null } : { ticks: [], head: 0 }
      m.set(key, s)
    }
    return s
  }
  const advance = (p, s, tick) => {
    if (p.kind === 'bucket') {
      if (s.at !== null) {
        s.tokens += p.refill * (tick - s.at)
        const max = p.capacity * p.per
        if (s.tokens > max) s.tokens = max
      }
      s.at = tick
    } else {
      while (s.head < s.ticks.length && s.ticks[s.head] <= tick - p.span) s.head++
    }
  }
  const allows = (p, s) => p.kind === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length - s.head) < p.limit
  const record = (p, s, tick) => {
    if (p.kind === 'bucket') s.tokens -= p.per
    else s.ticks.push(tick)
  }

  const out = []
  const per = new Map()
  let ta = 0, td = 0
  for (const [tick, key] of events) {
    let best = null
    for (const [pre, ps] of routes) {
      if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    let denied = null
    if (best !== null) {
      const ps = routes.get(best)
      const ss = ps.map((p) => stateOf(p, key))
      ps.forEach((p, i) => advance(p, ss[i], tick))
      for (let i = 0; i < ps.length; i++) if (!allows(ps[i], ss[i])) { denied = ps[i]; break }
      if (!denied) ps.forEach((p, i) => record(p, ss[i], tick))
    }
    const c = per.get(key) || (per.set(key, { a: 0, d: 0 }), per.get(key))
    if (denied) { c.d++; td++ } else { c.a++; ta++ }
    out.push(denied ? `${tick} ${key} deny ${denied.name}` : `${tick} ${key} allow`)
  }
  if (mode === 'replay') {
    process.stdout.write(out.map((l) => l + '\n').join(''))
  } else {
    const keys = [...per.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    let s = ''
    for (const k of keys) s += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
    s += `total allowed=${ta} denied=${td}\n`
    process.stdout.write(s)
  }
}

function die(msg) {
  process.stderr.write(msg + '\n')
  process.exitCode = 2
}

