import { parseAddr, keyOf } from './sheet.js'
import { parseFormula, hasMisplacedRange, rangeCells, collectRefs } from './formula.js'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (c) => ({ t: 'err', v: c })
const num = (v) => ({ t: 'num', v })
const isErr = (x) => x.t === 'err'

function literal(c) {
  if (c === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
  if (ERRS.includes(c)) return err(c)
  return { t: 'text', v: c }
}

