export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = letters.length === 1 ? letters.charCodeAt(0) - 64 : 26 * (letters.charCodeAt(0) - 64) + letters.charCodeAt(1) - 64
  return { col, row, key: letters + row }
}

export function colName(col) {
  if (col <= 26) return String.fromCharCode(64 + col)
  const c = col - 27
  return String.fromCharCode(65 + Math.floor(c / 26)) + String.fromCharCode(65 + (c % 26))
}
export const keyOf = (col, row) => colName(col) + row

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]?/.exec(line)
    const token = m[1]
    let rest = line.slice(token.length)
    rest = rest.replace(/^[ \t]+/, '')
    const a = parseAddr(token)
    if (!a) {
      const e = new Error(`line ${i + 1}: invalid cell address ${token}`)
      e.sheetError = true
      throw e
    }
    if (cells.has(a.key)) {
      const e = new Error(`line ${i + 1}: cell ${a.key} is declared twice`)
      e.sheetError = true
      throw e
    }
    cells.set(a.key, { col: a.col, row: a.row, key: a.key, content: rest })
  })
  return [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
}
