// static check: a range anywhere but directly as call argument
export function hasMisplacedRange(n) {
  switch (n.k) {
    case 'range': return true
    case 'bin': return hasMisplacedRange(n.l) || hasMisplacedRange(n.r)
    case 'un': case 'paren': return hasMisplacedRange(n.e)
    case 'call': return n.args.some((a) => a.k !== 'range' && hasMisplacedRange(a))
    default: return false
  }
}

export function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: c, row: r })
  return out
}

export function collectRefs(n, set) {
  switch (n.k) {
    case 'ref': { const a = parseAddr(n.a); if (a) set.set(a.key, a); break }
    case 'range': {
      const cs = rangeCells(n.a, n.b)
