  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depUses.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}
for (const names of depUses) {
  for (const x of names) if (!cost.has(x)) fail(`error: unknown task ${x}`)
}
const lt = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
const names = [...cost.keys()].sort(lt)
for (const x of names) deps.set(x, new Set())
for (const [t, ...ds] of depUses) for (const d of ds) deps.get(t).add(d)
const dl = new Map(names.map((x) => [x, [...deps.get(x)].sort(lt)]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (x) => {
    state.set(x, 1)
    stack.push(x)
    for (const d of dl.get(x)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d)).concat(d)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(x, 2)
  }
  for (const x of names) if (!state.get(x)) visit(x)
}

// topological order (deps first) via memoized recursion
const start = new Map(), finish = new Map(), depth = new Map()
const calc = (x) => {
  if (finish.has(x)) return
  let s = 0n, d = 0
  for (const y of dl.get(x)) {
    calc(y)
    if (finish.get(y) > s) s = finish.get(y)
    if (depth.get(y) + 1 > d) d = depth.get(y) + 1
  }
  start.set(x, s); finish.set(x, s + cost.get(x)); depth.set(x, d)
}
for (const x of names) calc(x)
let total = 0n
for (const x of names) if (finish.get(x) > total) total = finish.get(x)

const out = []
if (mode === 'waves') {
  const byDepth = []
  for (const x of names) (byDepth[depth.get(x)] ||= []).push(x)
  byDepth.forEach((g, k) => out.push(`wave ${k}: ${g.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const x of names) out.push(`${x} start=${start.get(x)} finish=${finish.get(x)} depth=${depth.get(x)}`)
  out.push(`total ${total}`)
} else {
  const prio = new Map()
  const users = new Map(names.map((x) => [x, []]))
  for (const x of names) for (const d of dl.get(x)) users.get(d).push(x)
  const pr = (x) => {
    if (prio.has(x)) return prio.get(x)
    let m = 0n
    for (const u of users.get(x)) { const p = pr(u); if (p > m) m = p }
    prio.set(x, m + cost.get(x))
    return m + cost.get(x)
  }
  names.forEach(pr)
  const freeAt = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const done = new Map()
  let remaining = names.length
  let t = 0n
  let makespan = 0n
  while (remaining > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let best = null
      for (const x of names) {
        if (done.has(x)) continue
        if (!dl.get(x).every((d) => done.has(d) && done.get(d) <= t)) continue
        if (best === null || prio.get(x) > prio.get(best)) best = x
      }
      if (best === null) break
      const f = t + cost.get(best)
      done.set(best, f)
      freeAt[w] = f
      ran[w].push(`${best}@${t}-${f}`)
      if (f > makespan) makespan = f
      remaining--
    }
    if (remaining === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => out.push(`worker ${i}:` + r.map((s) => ' ' + s).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
